	privPath := filepath.Join(*out, "private.pem")
	pubPath := filepath.Join(*out, "public.pem")
	if err := writePEM(privPath, "RSA PRIVATE KEY", x509.MarshalPKCS1PrivateKey(priv), 0o600); err != nil {
		return err
	}
	der, err := x509.MarshalPKIXPublicKey(&priv.PublicKey)
	if err != nil {
		return err
	}
	if err := writePEM(pubPath, "PUBLIC KEY", der, 0o644); err != nil {
		return err
	}
	fmt.Println("[+] private:", privPath)
	fmt.Println("[+] public :", pubPath)
	return nil
}

